#include <bits/stdc++.h>
using namespace std;
#define int long long

int main() {
	int t;
	cin>>t;
	
	while(t--){
	    int n;
	    cin>>n;
	    
	    vector<int> v(n);
	    for(int i=0;i<n;i++){
	        cin>>v[i];
	    }
	    
	    sort(v.rbegin(),v.rend());
	    int l=0,r=n-1;
	    int ans=0;
	    while(l>r){
	        int a=6*v[l],b=4*v[l]+4*v[l+1],c=3*v[l]+3*v[l+1]+3*v[l+2];
	        int maxi=max(a,b,c);
	        if(maxi==a){
                ans+=a;
                l++;r--;r--;
	        }
	        else if(maxi==b){
	            ans+=b;
	            l++;l++;
	            r--;
	        }
	        else{
	            ans+=c;
	            l++;l++;l++;
	        }
	    }
	    cout<<ans<<endl;
	}

}
